// Count how many independent newsrooms carry each claim.
// Three articles from one outlet are one source, not three, so every URL is
// resolved to its registrable domain before counting.
const settings = $('Research settings').first().json;
const minSources = Number(settings.minSourcesToCorroborate) || 2;
const maxFindings = Number(settings.maxFindings) || 6;

const domainOf = (url) => {
  try {
    return new URL(url).hostname.replace(/^www\./, '').toLowerCase();
  } catch {
    return '';
  }
};

const summaries = [];
const raw = [];

for (const item of $input.all()) {
  const result = item.json.output ?? item.json;
  if (result.summary) summaries.push(result.summary);
  for (const finding of result.findings ?? []) raw.push(finding);
}

const seen = new Set();
const findings = [];

for (const finding of raw) {
  const key = (finding.claim ?? '').trim().toLowerCase();
  if (!key || seen.has(key)) continue;
  seen.add(key);

  const byDomain = new Map();
  for (const source of finding.sources ?? []) {
    const domain = domainOf(source.url);
    if (!domain || byDomain.has(domain)) continue;
    byDomain.set(domain, {
      publisher: source.publisher || domain,
      url: source.url,
      domain,
      country: source.country || '',
      published: source.published || '',
    });
  }

  const sources = [...byDomain.values()];
  if (sources.length === 0) continue;

  findings.push({
    claim: finding.claim.trim(),
    sources,
    source_count: sources.length,
    status: sources.length >= minSources ? 'corroborated' : 'single-source',
  });
}

// Best-evidenced claims lead the briefing.
findings.sort((a, b) => b.source_count - a.source_count);
const kept = findings.slice(0, maxFindings);

const domains = new Set(kept.flatMap((f) => f.sources.map((s) => s.domain)));
const countries = new Set(
  kept.flatMap((f) => f.sources.map((s) => s.country).filter(Boolean)),
);

return [
  {
    json: {
      question: settings.chatInput ?? '',
      summary: summaries.join(' '),
      findings: kept,
      stats: {
        finding_count: kept.length,
        corroborated: kept.filter((f) => f.status === 'corroborated').length,
        single_source: kept.filter((f) => f.status === 'single-source').length,
        domain_count: domains.size,
        country_count: countries.size,
        min_sources: minSources,
      },
    },
  },
];

// Render the verified claims as a chat reply, and flatten the same claims
// into one row each for the Google Sheets audit trail.
const { question, summary, findings, stats } = $input.first().json;

const lines = [];
if (summary) lines.push(summary, '');

findings.forEach((finding, index) => {
  const outlets = finding.source_count === 1 ? 'outlet' : 'independent outlets';
  const label =
    finding.status === 'corroborated'
      ? `Corroborated — ${finding.source_count} ${outlets}`
      : `Single source — not confirmed elsewhere`;

  lines.push(`**${index + 1}. ${finding.claim}**`);
  lines.push(`_${label}_`);
  for (const source of finding.sources) {
    lines.push(`- [${source.publisher}](${source.url})`);
  }
  lines.push('');
});

const spread = [`${stats.domain_count} domains`];
if (stats.country_count) spread.push(`${stats.country_count} countries`);
lines.push(
  `_Source spread: ${spread.join(', ')}. ${stats.corroborated} of ${stats.finding_count} claims met the ${stats.min_sources}-source bar._`,
);

if (stats.single_source > 0) {
  const plural = stats.single_source === 1 ? 'claim rests' : 'claims rest';
  lines.push(
    `_${stats.single_source} ${plural} on a single outlet — treat as unconfirmed._`,
  );
}

const savedAt = new Date().toISOString();

return [
  {
    json: {
      briefing: lines.join('\n'),
      question,
      findings: findings.map((finding) => ({
        saved_at: savedAt,
        question,
        claim: finding.claim,
        status: finding.status,
        source_count: finding.source_count,
        publishers: finding.sources.map((s) => s.publisher).join(', '),
        urls: finding.sources.map((s) => s.url).join(' '),
      })),
    },
  },
];
